def build(out):
    P = 'dlc08'
    out.pack(P, 'Грузовые контейнеры и кубические отели', 'Cargo Containers & Cube Hotels')
    e = find(P, 'ГРУЗОВЫЕ КОНТЕЙНЕРЫ')
    for i, (n, code, zone, info) in enumerate(CUBES, 1):
        out.add(P, 'property', n, cost=0, Group='Кубический отель', Info=info, Lib=e['id'], Page=3,
                Extra={'code': code, 'zone': zone, 'rent': '500', 'roll': str(i), 'type': 'cube'})
    for i, (n, code, zone, info) in enumerate(CONTAINERS, 1):
        out.add(P, 'property', n, cost=0, Group='Грузовой контейнер', Info=info, Lib=e['id'], Page=4,
                Extra={'code': code, 'zone': zone, 'rent': '1000', 'roll': str(i), 'type': 'container'})
    out.add(P, 'gear', 'Мебель: бывшая в употреблении', cost=50, Group='Мебель (контейнер)', Lib=e['id'], Page=5,
            Info='Раскладушка, складной карточный столик, пластиковые ящики на шлакоблоках и доски; кресло в пятнах и с запахом.')
    out.add(P, 'gear', 'Мебель: стиль грузового контейнера', cost=100, Group='Мебель (контейнер)', Lib=e['id'], Page=5,
            Info='Кровать нормального размера, пластиковый комод, стол со стеллажом, кресло с намёком на обивку. Базовая мебель контейнера; хозяин ничего не заменит, если сломаете.')
    out.add(P, 'gear', 'Мебель: дотронуться до роскоши', cost=500, Group='Мебель (контейнер)', Lib=e['id'], Page=5,
            Info='Упругая кровать, комод и стол под дерево, удобное кресло, картины на стенах. Красивый контейнер привлекает внимание местных банд.')
    out.add(P, 'gear', 'Кофф-Поппер от «Континентал Брендс»', cost=50, Group='Аксессуары для дома', Lib=e['id'], Page=5,
            Info='Термос: вставьте Кофф-Поп, налейте воды, нажмите кнопку — через минуту 240 мл тепловатого кофеинового напитка. Кофф-Попсы продаются в «Оазисе»: 10 шт. за 10eb. Входят в любой образ жизни выше «Киббла».')
    out.add(P, 'gear', 'Огнеупорный сейф', cost=100, Group='Аксессуары для дома', Lib=e['id'], Page=5,
            Info='Ящик ~30 см, как толстая сталь (50 ПЗ), механический замок: Взлом замков СЛ 15. Можно унести за ручку.')
    out.add(P, 'gear', 'Потайной ящик', cost=100, Group='Аксессуары для дома', Lib=e['id'], Page=5,
            Info='Ячейка 15×30×7,5 см в кровати, столе или комоде: найти — Скрытие/раскрытие объекта СЛ 15.')
    out.add(P, 'gear', 'Умный туалетный столик', cost=500, Group='Аксессуары для дома', Lib=e['id'], Page=5,
            Info='Станция ухода за собой с цифровым зеркалом: подсветка, фильтры, синхронизация с агентом, примерка причёсок и косметики в реальном времени.')
    out.add(P, 'gear', 'Настенное искусство', cost=20, Group='Аксессуары для дома', Lib=e['id'], Page=5,
            Info='Постер в дешёвой пластиковой рамке (Моне или собаки, играющие в покер).')
